                if( have_rows('faq_items', 'option') ) :
                    while( have_rows('faq_items', 'option') ) : the_row(); 
                ?>

                    <!-- 
                      ITEM DINÂMICO DO FAQ
                      - O 'group' é para o Tailwind (group-[.open])
