                    -->
                    <div class="faq-item group border-t border-brand-marrom/50 pl-5 py-6">
                        <button class="faq-question w-full flex justify-between items-center text-left">
                            
                            <!-- 
                              O 'span' muda de cor com 'group-[.open]:text-brand-marrom'
                              e no hover. A cor base é 'text-brand-azul-escuro'.
                            -->
                            <span class="text-2xl font-serif text-brand-azul-escuro flex items-center gap-2 group-hover:text-brand-marrom group-[.open]:text-brand-marrom transition-colors duration-200">
                                
                                <!-- Ícone de 'Menos' (-) -->
                                <svg class="icon-minus w-3 h-3 hidden group-[.open]:block" width="8" height="1" viewBox="0 0 8 1" fill="none" xmlns="http://www.w3.org/2000/svg">
                                    <rect width="8" height="1" fill="currentColor"/>
                                </svg>

                                <!-- Ícone de 'Mais' (+) -->
                                <svg class="icon-plus w-3 h-3 block group-[.open]:hidden" width="8" height="8" viewBox="0 0 8 8" fill="none" xmlns="http://www.w3.org/2000/svg">
