           <!-- 
                COLUNA DIREITA (Posts Dinâmicos)
                - 100% no mobile (implícito)
                - 50% no desktop (lg:w-1/2)
            -->
            <div class="lg:w-1/2 space-y-12 mt-12 lg:mt-0">
                
                <?php
                // 1. Obter a lista de IDs de posts fixos
                $sticky_posts = get_option('sticky_posts');

                // 2. Definir os argumentos da query
                $args = array(
                    'post_type'           => 'post',        // O tipo de post (padrão)
                    'posts_per_page'      => 2,             // Limite de 2 posts
                    'post__in'            => $sticky_posts, // Apenas os posts que estão na lista de fixos
                    'ignore_sticky_posts' => 1              // Impede que o WP faça o comportamento padrão de "sticky"
                );

                $faq_posts_query = new WP_Query( $args );

                // 3. Iniciar o Loop
                if ( $faq_posts_query->have_posts() ) :
                    while ( $faq_posts_query->have_posts() ) : $faq_posts_query->the_post(); 
                ?>
                
                    <!-- Item do Post Dinâmico -->
                    <div class="flex flex-col">
                        
                        <!-- Título do Post (agora é um link) -->
                        <h3 class="text-2xl font-serif text-brand-azul-escuro mb-4">
                            <a href="<?php the_permalink(); ?>" class="hover:text-brand-marrom transition-colors">
                                <?php the_title(); ?>
                            </a>
                        </h3>
                        
                        <!-- Resumo do Post -->
                        <div class="font-sans text-brand-azul-escuro/80 mb-4">
                            <?php the_excerpt(); // 'the_excerpt()' é melhor aqui para um resumo ?>
                        </div>
                        
